import java.util.PriorityQueue;

class Solution {
    public long maximumScore(int[] nums, String s) {
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        long ans = 0;
        for (int i = s.length() - 1; i >= 0; --i) {
            pq.offer(nums[i]);
            if (s.charAt(i) == '1') {
                ans += pq.poll();
            }
        }
        return ans;
    }
}

