from typing import List

class Solution:
    def maximumScore(self, nums: List[int], s: str) -> int:
        n = len(nums)
        suf = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            suf[i] = suf[i + 1] + (s[i] == '1')
        bit = [0] * (n + 1)

        def upd(i):
            i += 1
            while i <= n:
                bit[i] += 1
                i += i & -i

        def qry(i):
            i += 1
            r = 0
            while i > 0:
                r += bit[i]
                i -= i & -i
            return r

        ans = chosen = 0
        for p in sorted(range(n), key=lambda i: -nums[i]):
            if suf[p] - (chosen - qry(p - 1)) > 0:
                ans += nums[p]
                chosen += 1
                upd(p)
        return ans

