import java.util.*;

class Solution {
    public long maximumScore(int[] nums, String s) {
        int n = nums.length;
        int[] suf = new int[n + 1];
        for (int i = n - 1; i >= 0; --i) suf[i] = suf[i + 1] + (s.charAt(i) == '1' ? 1 : 0);
        int[] bit = new int[n + 1];
        Integer[] ord = new Integer[n];
        for (int i = 0; i < n; ++i) ord[i] = i;
        Arrays.sort(ord, (a, b) -> Integer.compare(nums[b], nums[a]));
        long ans = 0;
        int chosen = 0;
        for (int p : ord) {
            int below = 0;
            for (int i = p; i > 0; i -= i & -i) below += bit[i];
            if (suf[p] - (chosen - below) > 0) {
                ans += nums[p];
                ++chosen;
                for (int i = p + 1; i <= n; i += i & -i) bit[i]++;
            }
        }
        return ans;
    }
}

